import os
import torch
import random
import numpy as np


class Paths:
    """
    Central repository for file paths.
    """

    # Input Directories
    INPUT_ROOT = "./input"
    METADATA_DIR = "./metadata"

    # Metadata Files (Generated by previous steps)
    TRAIN_CSV = os.path.join(METADATA_DIR, "train.csv")
    VAL_CSV = os.path.join(METADATA_DIR, "val.csv")
    TEST_CSV = os.path.join(METADATA_DIR, "test.csv")

    # Raw Data
    DICOM_TRAIN_DIR = os.path.join(INPUT_ROOT, "train")
    DICOM_TEST_DIR = os.path.join(INPUT_ROOT, "test")
    SAMPLE_SUBMISSION = os.path.join(INPUT_ROOT, "sample_submission.csv")

    # Working & Output Directories
    # Specific cache directory for this experiment idea
    CACHE_DIR = "./working/idea_11"
    # Location to save the best model checkpoint
    MODEL_SAVE_PATH = os.path.join(CACHE_DIR, "best_model.pth")
    # Location for the final submission file
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")


class Data:
    """
    Data processing and augmentation hyperparameters.
    """

    # Image Configuration
    IMG_SIZE = 224
    IN_CHANNELS = 3  # RGB (MIP of 3 slabs)

    # Tri-Slab Configuration
    SLAB_COUNT = 3
    SLAB_OVERLAP = 0.15  # 15% overlap

    # Tabular Data Configuration
    # Features to be embedded and fed into the transformer
    TABULAR_FEATURES = ["Age", "Sex", "SmokingStatus", "Percent"]

    # Normalization (Standard ImageNet stats)
    IMAGENET_MEAN = [0.485, 0.456, 0.406]
    IMAGENET_STD = [0.229, 0.224, 0.225]


class Model:
    """
    Model architecture hyperparameters for Pyramid Dual-Axis Attention Network.
    """

    BACKBONE = "efficientnet_b0"
    PRETRAINED = True

    # Feature Extraction
    # We extract features from these stride levels of EfficientNet
    PYRAMID_LEVELS = [3, 5, 7]  # Corresponds roughly to strides 8, 16, 32

    # Dimensions
    # Projection dimension for all visual and tabular tokens
    EMBED_DIM = 256

    # Transformer Encoder Config
    NUM_HEADS = 4
    NUM_LAYERS = 2
    DROPOUT = 0.1

    # Output Head
    # Outputs: alpha (slope), sigma_base, sigma_growth
    OUTPUT_DIM = 3


class Training:
    """
    Training loop hyperparameters.
    """

    SEED = 42
    BATCH_SIZE = 16  # Adjusted for dual-backbone memory usage
    EPOCHS = 30

    # Optimization
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-2

    # Scheduler (Cosine Annealing)
    ETA_MIN = 1e-6

    # Early Stopping
    PATIENCE = 8

    # Metric / Loss Config
    MAX_ERROR_CLIP = 1000  # Clip absolute error at 1000ml
    MIN_SIGMA_CLIP = 70  # Clip confidence at 70ml


class System:
    """
    Hardware and system settings.
    """

    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"
    NUM_WORKERS = 4


def setup_directories():
    """
    Ensures all necessary working directories exist.
    """
    os.makedirs(Paths.CACHE_DIR, exist_ok=True)
    os.makedirs(Paths.SUBMISSION_DIR, exist_ok=True)


def setup_reproducibility(seed=Training.SEED):
    """
    Sets random seeds for Python, NumPy, and PyTorch to ensure reproducible results.
    """
    random.seed(seed)
    np.random.seed(seed)
    torch.manual_seed(seed)
    torch.cuda.manual_seed(seed)
    torch.backends.cudnn.deterministic = True
    torch.backends.cudnn.benchmark = False
    os.environ["PYTHONHASHSEED"] = str(seed)


# Initialize directories immediately upon import
setup_directories()
